+    fs::write(path, content).unwrap()
+}
+
+pub fn append_log(path: &Path, line: &str) {
+    let mut f = fs::OpenOptions::new().append(true).open(path).unwrap();
+    use std::io::Write;
+    writeln!(f, "{}", line).unwrap()
+}

